<section class="mt-7 grid gap-5 xl:grid-cols-2"><form action="<?= base_url('settings') ?>" method="post" class="card space-y-4 p-6"><?= csrf_field() ?><div><h2 class="text-lg font-extrabold">Workspace & white label</h2><p class="text-sm text-[#78908c]">Brand the product for each agency client.</p></div><label class="block text-xs font-bold">Workspace name<input name="name" required value="<?= esc($workspace['name']) ?>" class="field mt-2"></label><label class="block text-xs font-bold">Custom domain<input name="custom_domain" value="<?= esc($workspace['custom_domain']??'') ?>" placeholder="mail.yourdomain.com" class="field mt-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-xs font-bold">Timezone<select name="timezone" class="field mt-2"><option selected><?= esc($workspace['timezone']) ?></option><option>UTC</option><option>America/New_York</option></select></label><label class="text-xs font-bold">Brand color<input name="brand_color" type="color" value="<?= esc($workspace['brand_color']) ?>" class="field mt-2 h-12"></label></div><button class="btn btn-primary">Save settings</button></form><section class="card p-6"><h2 class="text-lg font-extrabold">SMTP delivery</h2><p class="text-sm text-[#78908c]">Connect Gmail, SES, Mailgun, SendGrid, Brevo or custom SMTP.</p><div class="mt-5 grid grid-cols-2 gap-3"><?php foreach(['Gmail','Amazon SES','Mailgun','SendGrid','Brevo','Custom SMTP'] as $provider): ?><button class="rounded-xl bg-[#e7f2ef] p-4 text-left text-sm font-bold shadow-insetsoft"><i data-lucide="server" class="mb-3 h-5 text-sea"></i><?= $provider ?></button><?php endforeach ?></div><p class="mt-5 rounded-xl bg-[#f5efe0] p-3 text-xs text-[#8a6d31]">Credentials are intentionally not collected until encrypted secret storage is configured.</p></section></section>
